(function(){
  "use strict";
  // IGDC Core language guard
  function getParam(name){
    try{
      var m = location.search.match(new RegExp("[?&]"+name+"=([^&]+)"));
      return m ? decodeURIComponent(m[1]) : null;
    }catch(e){ return null; }
  }
  function getStored(){
    try{ return localStorage.getItem("igdc_lang") || null; }catch(e){ return null; }
  }
  function setStored(lang){
    try{
      localStorage.setItem("igdc_lang", lang);
      document.cookie = "ui_lang="+encodeURIComponent(lang)+"; path=/; max-age="+(3600*24*365);
    }catch(e){}
  }
  function emitLangChange(lang){
    try{
      var ev;
      if(typeof CustomEvent === "function"){
        ev = new CustomEvent("igdc:langchange", { detail:{ lang:lang } });
      }else if(document && document.createEvent){
        ev = document.createEvent("CustomEvent");
        ev.initCustomEvent("igdc:langchange", false, false, { lang:lang });
      }
      if(ev && window && window.dispatchEvent) window.dispatchEvent(ev);
    }catch(e){}
  }

  var chosen = getParam("lang") || getStored();
  if(chosen){ try{ setStored(chosen); }catch(e){} }

  var origChange = window.changeLanguage;
  if(origChange && origChange.__igdcCoreLangGuarded) return;

  window.changeLanguage = function(l){
    var lang = (typeof l === "string" && l) ? l : (getStored() || chosen || "en");
    try{ setStored(lang); }catch(e){}
    if(typeof origChange === "function"){
      try{ origChange(lang); }catch(e){}
    }
    emitLangChange(lang);
  };
  window.changeLanguage.__igdcCoreLangGuarded = true;

  // Initialize once from chosen/stored value. Do not force overwrite without a value.
  (function(){
    var init = chosen || getStored();
    if(init){ try{ window.changeLanguage(init); }catch(e){} }
  })();
})();
